#include "common/benchmark.hpp"
#include "cfd/solvers/fvm/collocated_incompressible.hpp"
#include "cfd/fvm/poly_mesh.hpp"
#include <cmath>
int main(int argc,char**argv){using namespace cfd::examples;const auto o=parse_options(argc,argv);const std::size_t n=o.quick?8U:24U*o.scale;const std::size_t steps=o.quick?1U:8U;Timer setup;auto mesh=cfd::fvm::make_cartesian_hexa_mesh(n,n,1,1.0,1.0,1.0);cfd::fvm::CollocatedIncompressibleConfig cfg;cfg.dt=0.02;cfg.kinematic_viscosity=0.05;cfg.include_convection=true;cfg.pressure_correctors=2;cfg.nonorthogonal_correctors=0;cfg.momentum_iterations=120;cfg.pressure_iterations=300;cfg.momentum_tolerance=1e-8;cfg.pressure_tolerance=1e-8;cfd::fvm::CollocatedIncompressible s(std::move(mesh),cfg);for(const auto name:{"left","right","bottom"})s.set_velocity_boundary(name,cfd::fvm::VelocityBoundaryType::fixedValue);s.set_velocity_boundary("top",cfd::fvm::VelocityBoundaryType::fixedValue,{1.0,0.0,0.0});s.set_velocity_boundary("front",cfd::fvm::VelocityBoundaryType::slip);s.set_velocity_boundary("back",cfd::fvm::VelocityBoundaryType::slip);s.initialize_uniform();const double setup_ms=setup.milliseconds();Timer sim;for(std::size_t k=0;k<steps;++k)s.step_piso();const double sim_ms=sim.milliseconds();double checksum=s.continuity_l2();for(const auto&v:s.velocity())checksum+=std::abs(v.x)+std::abs(v.y);emit({"phase03_fvm","lid_driven_cavity_piso","cpu","cell_steps",s.mesh().cell_count(),steps,setup_ms,sim_ms,double(s.mesh().cell_count())*double(steps),checksum});return 0;}
